import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import {
    parseFormData,
    VlFormLabelComponent,
    VlFormMessageComponent,
    VlInputFieldComponent,
    VlSelectRichComponent,
} from '@domg-wc/components/form';

registerWebComponents([
    VlFormLabelComponent,
    VlInputFieldComponent,
    VlSelectRichComponent,
    VlFormMessageComponent,
    VlButtonComponent,
]);

// vl-select-rich krijgt zijn opties via de property options.
document.querySelector('#hobbies').options = [
    { label: 'Padel', value: 'padel' },
    { label: 'Dans', value: 'dans' },
    { label: 'Drummen', value: 'drummen' },
    { label: 'Zwemmen', value: 'zwemmen' },
    { label: 'Boardgames', value: 'boardgames' },
    { label: 'Fietsen', value: 'fietsen' },
    { label: 'Cocktails', value: 'cocktails' },
];

const form = document.querySelector('#form');
const output = document.querySelector('#form-data');

// Toont de geparste data onder de knoppen, of verbergt ze na een reset.
const showFormData = (data) => {
    output.textContent = data ? JSON.stringify(data, null, 10) : '';
    form.querySelectorAll('.form-data').forEach((column) => (column.hidden = !data));
};

// parseFormData geeft één waarde per veld, en een array voor een veld met het attribuut multiple (hier hobbies).
form.addEventListener('submit', (event) => {
    event.preventDefault();
    const data = parseFormData(form);
    console.log(data);
    showFormData(data);
});
form.addEventListener('reset', () => showFormData(null));
